from csv_import import tags_from_csv
from form_import import tags_from_form
from normalise import clean_token


def test_form_tags_typed_with_commas_do_not_keep_them():
    """The reported bug: 'urgent,' shows up as a tag."""
    assert tags_from_form("urgent, important") == ["urgent", "important"]


def test_form_trailing_comma_on_last_tag():
    assert tags_from_form("urgent, important,") == ["urgent", "important"]


def test_a_lone_separator_is_not_a_tag():
    assert tags_from_form(" Urgent , important ") == ["urgent", "important"]


def test_strip_order_leaves_no_whitespace_behind():
    """Stripping whitespace then commas leaves the space in ' urgent , '."""
    assert clean_token(" urgent , ") == "urgent"


def test_csv_path_still_works():
    assert tags_from_csv("Urgent, important,") == ["urgent", "important"]
    assert tags_from_csv("urgent,,important") == ["urgent", "important"]


def test_punctuation_inside_a_tag_is_kept():
    assert tags_from_form("c++ c# node.js front-end") == [
        "c++",
        "c#",
        "node.js",
        "front-end",
    ]

